# Ronde Z30: architectuur van de database (Rogier, 2026-10-31). Idempotent, additief, niets verwijderd.
import sqlite3,shutil,os,json,afgeleid
DT='2026-10-31';R='Rogier: architectuur verbeteren (ronde Z30), 2026-10-31';DB=os.environ.get('DB','canon.db')
if DB=='canon.db' and not os.path.exists('canon_backup_Z30.db'): shutil.copy('canon.db','canon_backup_Z30.db')
c=sqlite3.connect(DB);S={'toegevoegd':[],'vervangen':[],'wrijving':[],'gesloten':[],'vraag':[],'handleiding':0}
afgeleid.schema(c)
RONDE=c.execute("select max(ronde) from canon").fetchone()[0]
RONDE=RONDE if c.execute("select 1 from canon where code='BESLUIT-Z30-1'").fetchone() else RONDE+1
f=lambda code:c.execute('select feit from canon where code=?',(code,)).fetchone()[0]
B1=f('BESLUIT-1-Z1').replace('De noodstand 1 op 100 werd in jaar 0 door Ysa Maren en de Makers in het zaaischip aangezet.','De noodstand 1 op 100 (de Stille Modus) werd door Ysa Maren en de Makers in het zaaischip ontworpen; in jaar 0 activeerden de Raad der Moeders en de Dochters hem zonder het te weten (ORIGIN-10). Ysa stierf in -1209 en zette zelf niets aan.')
G=f('GEH-zegel-Z12').replace('door de Makers in jaar 0 aangezet (BESLUIT-1, BESLUIT-Z12-1)','door Ysa Maren en de Makers ontworpen en in jaar 0 door de Raad der Moeders zonder het te weten geactiveerd (ORIGIN-10, BESLUIT-Z30-1, BESLUIT-Z12-1)')
assert B1!=f('BESLUIT-1-Z1') and G!=f('GEH-zegel-Z12')
HARD='Harde lijnen (gelden voor elke rij, elk verhaal): alleen volwassenen (18+) in seksuele rollen; geen minderjarigen; geen dieren in een seksuele rol; nooit seks met wie echt niet kan instemmen; dwang tussen volwassenen alleen als gelabeld donker thema.'
N=[('BESLUIT-Z30-1','Besluit','Besluit 1 (Z30): wie legde en wie activeerde het Zegel',B1+' [Z30] Rechtzetting: vervangt BESLUIT-1-Z1, dat Ysa in jaar 0 liet aanzetten terwijl zij in -1209 stierf.','BESLUIT-1;BESLUIT-1-Z1;ORIGIN-10;TOESTAND-Z16-PER-v4-ysa-maren-3'),
('BESLUIT-Z30-2','Oorsprong','HET GEHEIM: de Zegel van Ves-Anath (Z30)',G+' [Z30] Rechtzetting: vervangt GEH-zegel-Z12 (jaar 0: activering door de Raad, niet door Ysa of de Makers).','GEH-zegel-Z12;ORIGIN-10;BESLUIT-Z30-1'),
('BESLUIT-Z30-3','Besluit','Draagkracht: Kern, Structuur, Kleur','Elke rij heeft een draagkracht. Kern: de oorzaak van de wereld, het Zegel, de 1-op-100 regel, harde grenzen, hoofdpersonen en tijdlijn-ankers; alleen te wijzigen via een nieuw BESLUIT. Structuur: mag schuiven, maar elke afwijking krijgt een wrijving-rij. Kleur: vrij, het verhaal mag het aanpassen. Bij twijfel wint het verhaal, behalve bij Kern. Classificatieregels staan in afgeleid.py en in de handleiding (HANDL-Z30-3).','afgeleid.py;HANDL-Z30-3'),
('BESLUIT-Z30-4','Besluit','Harde lijnen: één regel voor de hele canon',HARD+' Het herhaalde veiligheidslabel in losse rijen is vervangen door deze ene regel plus de vlag veilig_18plus en de verwijzing veilig_variant (tabel veiligheid_varianten). De oorspronkelijke tekst staat nog in kolom feit en in canon_backup_Z30.db.','REGEL-harde-grenzen;EROS-GRENZEN-Z6'),
('BESLUIT-Z30-5','Besluit','Kleur-regel voor botsingen','Botsen twee Kleur-rijen, dan is dat geen wrijving: het verhaal wint en de rij wordt aangepast (of op voorlopig, vervangen gezet). Alleen botsingen waarin een Kern- of Structuur-rij zit, krijgen een wrijving-rij.','BESLUIT-Z30-3'),
('BESLUIT-Z30-6','Besluit','Architectuur ronde Z30','Nieuwe kolommen in canon: draagkracht, ideeenbank, veilig_18plus, veilig_variant, vervangen_door, feit_schoon (feit zonder herhaald label en zonder rondenotities). Nieuwe tabellen: veiligheid_varianten, verwijzing (koppeltabel uit verwijst_naar), historie (rondenotities en origineel feit), handleiding. Views: v_actief, v_kern, v_ideeenbank, v_open, v_dode_links. Bestaande kolommen blijven onveranderd staan; afgeleide delen worden herbouwd met afgeleid.py. Zie SCHEMA.md.','BESLUIT-Z30-3;BESLUIT-Z30-4')]
for code,cat,o,ft,v in N:
  if not c.execute('select 1 from canon where code=?',(code,)).fetchone():
    c.execute("insert into canon(categorie,onderwerp,feit,status,reden,hangt_samen_met,ronde,code,verwijst_naar,jaar,tijdperk,functie,techniek) values(?,?,?,'vastgesteld',?,?,?,?,?,?,?,?,?)",(cat,o,ft,R,v,RONDE,code,v,0 if code in('BESLUIT-Z30-1','BESLUIT-Z30-2') else None,'0 Voortijd' if code in('BESLUIT-Z30-1','BESLUIT-Z30-2') else None,'WERELD','geen'));S['toegevoegd'].append(code)
for old,new in[('BESLUIT-1-Z1','BESLUIT-Z30-1'),('GEH-zegel-Z12','BESLUIT-Z30-2')]:
  if c.execute("select status from canon where code=?",(old,)).fetchone()[0]=='vastgesteld':
    c.execute("update canon set status='voorlopig, vervangen',reden=coalesce(reden,'')||?,vervangen_door=? where code=?",(f' [Ronde Z30: vervangen door {new}]',new,old));S['vervangen'].append(old)
W=[('WRIJ-Z30-1','Zegel in jaar 0: Ysa/Makers of de Raad der Moeders?','GEH-zegel-Z12, BESLUIT-1-Z1 tegen ORIGIN-10 en TOESTAND-Z16-PER-v4-ysa-maren-3','Twee vastgestelde rijen lieten Ysa (en de Makers) het Zegel in jaar 0 aanzetten; Ysa stierf in -1209. Opgelost met BESLUIT-Z30-1 en BESLUIT-Z30-2 (ontwerp: Ysa en de Makers; activering jaar 0: de Raad der Moeders, zonder het te weten).','opgelost','BESLUIT-Z30-1;BESLUIT-Z30-2;ORIGIN-10'),
('WRIJ-Z30-2','Stille Modus niet gezaaid in boek 0','ORIGIN-10 tegen de roman (ROMAN-Z16-roman)','De Stille Modus (1 jongen op 100, vonkcellen naar de overblijvende mannen) is de kern van de wereld, maar wordt in "The Body Is the Price" niet gezaaid. Voorstel: Ysa ontwerpt hem als boetedoening, Hesta laadt de cellen in; dat verklaart het blauwe licht in h31 (sluit dan ook WRIJ-Z21-5 en WRIJ-Z22-2). Tekst NIET gewijzigd; wacht op Rogiers ja (VRAAG-Z30-1).','open','ORIGIN-10;WRIJ-Z21-5;WRIJ-Z22-2;VRAAG-Z30-1'),
('WRIJ-Z30-3','Veiligheidslabel bestaat in varianten die inhoudelijk verschillen','alle rijen met veilig_variant','Zie tabel veiligheid_varianten (kolom afwijking). Vooral: variant "geen seksuele inhoud zonder instemming" is strenger dan de harde lijn (dwang tussen volwassenen mag als gelabeld donker thema); enkele varianten zeggen "geweld en horror mogen hard", andere niet; één variant noemt het Jongenshof (niet-seksueel). Aanbeveling: BESLUIT-Z30-4 geldt als enige regel; Rogier beslist of de strengere/extra formuleringen per rij betekenis hebben.','open','BESLUIT-Z30-4'),
('WRIJ-Z30-4','Dode links in verwijst_naar','BESLUIT-Z19-2 -> PER-v4-corran; BESLUIT-Z25-2 -> BESLUIT-Z25-8; BESLUIT-Z26-1 -> ROMAN-Z16-h5','Gevonden met view v_dode_links (Z30): 3 verwijzingen naar codes die niet bestaan (24.326 verwijzingen gecontroleerd). Waarschijnlijk tikfouten (bijv. ROMAN-Z16-h05). Klein; niet automatisch hersteld.','open (klein)','BESLUIT-Z19-2;BESLUIT-Z25-2;BESLUIT-Z26-1')]
for code,t,d,b,st,v in W:
  if not c.execute('select 1 from wrijving where code=?',(code,)).fetchone():
    c.execute('insert into wrijving(titel,delen_die_botsen,beschrijving,type,status,code,verwijst_naar) values(?,?,?,?,?,?,?)',(t,d,b,'Z30',st,code,v));S['wrijving'].append(code)
SL=[('WRIJ-Z15-5','Ingehaald door TOESTAND-Z16-PER-v4-ysa-maren-3 (vastgesteld: Ysa sterft in -1209).'),('WRIJ-Z20-3','Ingehaald door BESLUIT-Z19-3 en de roman: de tomaten worden rood (h33, Ysa geeft de tomaat aan Sabe).')]
for code,why in SL:
  if c.execute('select status from wrijving where code=?',(code,)).fetchone()[0].startswith('open'):
    c.execute("update wrijving set status='opgelost',beschrijving=beschrijving||? where code=?",(f' [Z30 gesloten {DT}] {why}',code));S['gesloten'].append(code)
if not c.execute("select 1 from open_vraag where code='VRAAG-Z30-1'").fetchone():
  c.execute("insert into open_vraag(vraag,waarom_belangrijk,status,antwoord,code,verwijst_naar) values(?,?,?,?,?,?)",('Zaaien we de Stille Modus in boek 0 (Ysa ontwerpt hem als boetedoening, Hesta laadt de cellen in, blauw licht h31)?','Het is de oorzaak van de wereld en nu onzichtbaar in boek 0; sluit WRIJ-Z30-2, WRIJ-Z21-5, WRIJ-Z22-2.','open','Aanbeveling: ja (verandert de romantekst; wacht op Rogier).','VRAAG-Z30-1','WRIJ-Z30-2;ORIGIN-10'));S['vraag'].append('VRAAG-Z30-1')
H=[('HANDL-Z30-1','Bron en status','canon.db is de bron. Statussen: vastgesteld (Rogiers keuze), voorlopig (voorstel), voorlopig, vervangen (oud, zie vervangen_door), vervallen (negeren). Nooit rijen verwijderen: vervang door een nieuwe rij en zet de oude op voorlopig, vervangen.'),
('HANDL-Z30-2','Harde lijnen',HARD+' Dit is één regel (BESLUIT-Z30-4) en hoeft niet in elk feit te staan.'),
('HANDL-Z30-3','Draagkracht','Kern: alleen wijzigen via een nieuw BESLUIT. Structuur: mag schuiven, met een wrijving-rij. Kleur: vrij. Bij twijfel wint het verhaal, behalve bij Kern. Regels (afgeleid.py): '+afgeleid.REGELS.replace('\n',' ')),
('HANDL-Z30-4','Kleur-regel','Botsing tussen twee Kleur-rijen is geen wrijving: het verhaal wint, pas de rij aan. Alleen botsingen met Kern of Structuur krijgen een wrijving-rij.'),
('HANDL-Z30-5','Wat lezen','Schrijvers: v_kern (heilig), v_actief (levende canon, schone tekst), v_open (open wrijvingen en vragen), v_ideeenbank (catalogi: inspiratie, geen canon). Hulpscript: python3 vraag.py kern|zoek <woord>|code <CODE>|open.'),
('HANDL-Z30-6','Afgeleide delen','draagkracht, ideeenbank, veilig_*, feit_schoon, verwijzing, historie en veiligheid_varianten worden herbouwd met python3 afgeleid.py. Dode links: view v_dode_links.')]
for code,o,t in H:
  if not c.execute('select 1 from handleiding where code=?',(code,)).fetchone(): c.execute('insert into handleiding(code,onderwerp,tekst) values(?,?,?)',(code,o,t));S['handleiding']+=1
if not c.execute("select 1 from logboek where wat like 'Ronde Z30: %'").fetchone(): c.execute("insert into logboek(datum,wat) values(?,?)",(DT,'Ronde Z30: architectuur. BESLUIT-Z30-1..6; GEH-zegel-Z12 en BESLUIT-1-Z1 -> voorlopig, vervangen; WRIJ-Z30-1..3; WRIJ-Z15-5 en WRIJ-Z20-3 gesloten; VRAAG-Z30-1; kolommen draagkracht/ideeenbank/veilig_18plus/veilig_variant/vervangen_door/feit_schoon; tabellen veiligheid_varianten, verwijzing, historie, handleiding; views v_actief, v_kern, v_ideeenbank, v_open, v_dode_links. Origineel van elk feit onveranderd in kolom feit en in canon_backup_Z30.db.'))
c.execute("update canon set verwijst_naar='HANDL-Z30-3;BESLUIT-Z30-5',hangt_samen_met='HANDL-Z30-3;BESLUIT-Z30-5' where code='BESLUIT-Z30-3' and verwijst_naar like '%afgeleid.py%'")
c.commit();afgeleid.bouw(c)
S['draagkracht']=dict(c.execute('select draagkracht,count(*) from canon group by 1').fetchall());S['totaal']=c.execute('select count(*) from canon').fetchone()[0]
os.makedirs('z30',exist_ok=True);json.dump(S,open('z30/stats.json','w'),ensure_ascii=False,indent=1);print(json.dumps(S,ensure_ascii=False))
